import{_ as a,o,c as d,a2 as n}from"./chunks/framework.BM5YPQmL.js";const h=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"architecture.md","filePath":"architecture.md"}'),s={name:"architecture.md"};function c(r,e,i,t,p,l){return o(),d("div",null,[...e[0]||(e[0]=[n(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>Pidrang is an Nx monorepo of small packages with a strict dependency direction: everything depends on <code>@pidrang/core</code>, and core depends on nothing but <code>@angular/core</code>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                    @pidrang/core</span></span>
<span class="line"><span>        (contracts, providePidrang, signals)</span></span>
<span class="line"><span>                          |</span></span>
<span class="line"><span>     +----------+---------+----------+</span></span>
<span class="line"><span>     |          |                    |</span></span>
<span class="line"><span>@pidrang/    @pidrang/          @pidrang/</span></span>
<span class="line"><span>supabase     material           tailwind</span></span>
<span class="line"><span>     |          |                    |</span></span>
<span class="line"><span>  Supabase   Angular Material   Tailwind CSS</span></span></code></pre></div><h2 id="packages" tabindex="-1">Packages <a class="header-anchor" href="#packages" aria-label="Permalink to &quot;Packages&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pidrang/</span></span>
<span class="line"><span>├── apps/</span></span>
<span class="line"><span>│   ├── demo-material/   Angular demo (Material UI)</span></span>
<span class="line"><span>│   ├── demo-tailwind/   Angular demo (Tailwind UI)</span></span>
<span class="line"><span>│   └── pidrang-cli/     the \`pidrang\` command line entry point</span></span>
<span class="line"><span>└── libs/</span></span>
<span class="line"><span>    ├── core/            headless primitives and contracts (@pidrang/core)</span></span>
<span class="line"><span>    ├── supabase/        Supabase DataProvider and AuthProvider (@pidrang/supabase)</span></span>
<span class="line"><span>    ├── material/        Angular Material UI layer (@pidrang/material)</span></span>
<span class="line"><span>    ├── tailwind/        Tailwind CSS UI layer (@pidrang/tailwind)</span></span>
<span class="line"><span>    ├── cli/             provider-agnostic wizard and codegen (@pidrang/cli)</span></span>
<span class="line"><span>    ├── cli-supabase/    Supabase schema introspection for the CLI (@pidrang/cli-supabase)</span></span>
<span class="line"><span>    ├── provider-conformance/  shared DataProvider contract tests, used by specs only (private)</span></span>
<span class="line"><span>    └── adapter-coexistence/   renders both UI layers in one component, test only (private)</span></span></code></pre></div><h2 id="pidrang-core" tabindex="-1"><code>@pidrang/core</code> <a class="header-anchor" href="#pidrang-core" aria-label="Permalink to &quot;\`@pidrang/core\`&quot;">​</a></h2><p>Framework-native (Angular) but UI-agnostic. It depends on <code>@angular/core</code> only, never on a component library, <code>@angular/common</code>, <code>@angular/forms</code> or <code>@angular/router</code>. Subpaths of <code>@angular/core</code> are allowed, <code>rxjs</code> is not. That boundary is what lets any UI layer or data source be added without touching core.</p><ul><li><code>Resource</code> (optionally described with <code>Field</code> and <code>FieldType</code> for a typed form or table), <code>DataProvider</code>, <code>ListParams</code> (with typed <code>Filter</code>s: <code>normalizeFilters</code>, <code>validateListParams</code>, <code>rejectUnsupportedFilters</code>) and <code>ListResult&lt;T&gt;</code>, <code>GetOneParams</code>, <code>CreateParams&lt;T&gt;</code>, <code>UpdateParams&lt;T&gt;</code>, <code>DeleteParams</code></li><li><code>providePidrang({ dataProvider, resources, authProvider? })</code> for app-wide configuration</li><li><code>injectDataProvider()</code>, <code>injectAuthProvider()</code>, <code>injectResources()</code>, <code>injectResource(name)</code> for reading that configuration</li><li><code>injectResourceList&lt;T&gt;(resourceName, params?)</code>, a signal-based list loader built on Angular&#39;s native <code>resource()</code></li><li><code>injectAuthSession()</code>, a signal-based view of the current identity, returned as an <code>AuthSessionRef</code></li><li><code>PidrangError</code>, the error type data and auth providers throw, with a <code>category</code> (<code>unauthenticated</code>, <code>forbidden</code>, <code>not-found</code>, <code>unknown</code>) plus <code>code</code>, <code>status</code> and <code>cause</code></li></ul><p><code>AuthProvider</code> (<code>login</code>, <code>logout</code>, <code>getIdentity</code>, optional <code>onSessionChange</code>) follows the same pattern as <code>DataProvider</code>: <code>providePidrang</code> registers it, <code>injectAuthProvider()</code> reads it, and <code>injectAuthSession()</code> returns an <code>AuthSessionRef</code> built on <code>resource()</code>. Its <code>value()</code> is <code>AuthIdentity | null | undefined</code> (signed in, signed out, not loaded yet), keeps the previous identity while a session change reloads it, and never throws: a provider failure goes to <code>error()</code> and leaves <code>value()</code> <code>undefined</code>. A provider that implements <code>onSessionChange(listener)</code> makes every live <code>injectAuthSession()</code> reload on login, logout or an external auth change, and unsubscribes it when destroyed. <code>reload()</code> also works for providers without it.</p><h2 id="pidrang-supabase" tabindex="-1"><code>@pidrang/supabase</code> <a class="header-anchor" href="#pidrang-supabase" aria-label="Permalink to &quot;\`@pidrang/supabase\`&quot;">​</a></h2><p>Implements <code>DataProvider</code> and <code>AuthProvider</code> against <code>@supabase/supabase-js</code>:</p><ul><li><code>SupabaseDataProvider</code> and <code>provideSupabaseDataProvider({ client })</code> map <code>ListParams</code> to PostgREST filters (<code>eq</code>, <code>neq</code>, <code>lt</code>, <code>lte</code>, <code>gt</code>, <code>gte</code>, an escaped <code>in</code> list, <code>imatch</code> with an escaped pattern for <code>contains</code>, <code>is</code>), <code>.order()</code> and <code>.range()</code>, reject a filter field that PostgREST would read as a query option or a path (<code>order</code>, <code>limit</code>, <code>a.b</code>, <code>a-&gt;b</code>) and a sorter field holding path syntax, and normalize <code>PostgrestError</code> to a <code>PidrangError</code> whose <code>category</code> comes from the HTTP status (except 42883, a missing operator, which stays <code>unknown</code>), so an app can ask for sign-in on <code>unauthenticated</code> only, never on a signed-in user&#39;s Row Level Security denial. <code>getList</code> always adds <code>id</code> ascending as a final sort, unless a sorter already targets <code>id</code>, so pages never repeat or skip rows.</li><li><code>SupabaseAuthProvider</code> and <code>provideSupabaseAuthProvider({ client })</code> wrap Supabase Auth. A missing session (<code>AuthSessionMissingError</code>, <code>session_not_found</code>) is a <code>null</code> identity; network and server failures are thrown as <code>PidrangError</code>. Supabase auth events drive <code>onSessionChange</code>, and a repeated <code>SIGNED_IN</code> for the same user (sent when a tab regains focus) is ignored.</li></ul><p>Both factories return plain objects and do not use Angular DI. The app wires them in through <code>providePidrang</code>.</p><p>Every table is assumed to have an <code>id</code> primary key: <code>getOne</code>, <code>update</code> and <code>delete</code> filter on it.</p><h3 id="access-control-is-your-responsibility" tabindex="-1">Access control is your responsibility <a class="header-anchor" href="#access-control-is-your-responsibility" aria-label="Permalink to &quot;Access control is your responsibility&quot;">​</a></h3><p><code>SupabaseDataProvider</code> and <code>SupabaseAuthProvider</code> perform no authorization. Every access guarantee comes from the Row Level Security policies on your own Supabase project. Pidrang assumes those policies are correctly configured; it does not enforce or verify them.</p><h2 id="ui-layers" tabindex="-1">UI layers <a class="header-anchor" href="#ui-layers" aria-label="Permalink to &quot;UI layers&quot;">​</a></h2><p><code>@pidrang/material</code> and <code>@pidrang/tailwind</code> expose the same schema-driven components:</p><ul><li><code>ResourceTable</code> renders a <code>Resource</code>&#39;s <code>Field[]</code> as a table. A projected <code>#actions</code> template (<code>contentChild</code> and <code>ngTemplateOutlet</code>) becomes a trailing column for per-row buttons and links.</li><li><code>ResourceForm</code> renders one input per <code>Field</code>, built on Angular Signal Forms (<code>@angular/forms/signals</code>). A <code>linkedSignal</code> draft resets whenever its <code>value</code> input changes and never mutates the caller&#39;s original object.</li></ul><p>They depend on <code>@pidrang/core</code> and their own styling stack, never on a specific <code>DataProvider</code>. They therefore work with <code>@pidrang/supabase</code> today and any future data provider unchanged.</p><p><code>@pidrang/tailwind</code> ships no CSS. The consuming app&#39;s Tailwind build, through its own <code>@source</code> scan, turns the classes used in the library&#39;s templates into styles.</p><h2 id="cli" tabindex="-1">CLI <a class="header-anchor" href="#cli" aria-label="Permalink to &quot;CLI&quot;">​</a></h2><p><code>@pidrang/cli</code> is the provider-agnostic engine behind <code>pidrang init</code>: the interactive wizard, the <code>Resource</code> codegen and the <code>SchemaProvider</code> contract every schema source implements. <code>@pidrang/cli-supabase</code> implements it for Supabase with three connection strategies: GraphQL introspection (<code>pg_graphql</code>), the REST OpenAPI document (service role key) and direct Postgres (<code>information_schema</code>). <code>apps/pidrang-cli</code> wires the two together.</p><h2 id="adding-a-data-source-or-ui-package" tabindex="-1">Adding a data source or UI package <a class="header-anchor" href="#adding-a-data-source-or-ui-package" aria-label="Permalink to &quot;Adding a data source or UI package&quot;">​</a></h2><p>New packages such as <code>@pidrang/ng-zorro</code>, <code>@pidrang/rest</code>, <code>@pidrang/graphql</code> depend on <code>@pidrang/core</code> only. If adding one requires changing core, treat that as a design smell and re-examine the core contract first.</p><p>The reasons behind non-obvious implementation choices are in <a href="./design-notes">Design notes</a>. The data provider contract, with its filter semantics and conformance suite, is in <a href="./data-providers">Writing a data provider</a>.</p>`,26)])])}const g=a(s,[["render",c]]);export{h as __pageData,g as default};
